            (aux0_0.p_0member);
          dx_0liq = Modelica_Media_Water_IF97x_0Utilities_rholx_0T(aux0_0.
            T_0member);
          dx_0vap = Modelica_Media_Water_IF97x_0Utilities_rhovx_0T(aux0_0.
            T_0member);
          fl0_0 = Modelica_Media_Water_IF97x_0Utilities_BaseIF97_Basic_f3(
            dx_0liq, aux0_0.T_0member);
          fv0_0 = Modelica_Media_Water_IF97x_0Utilities_BaseIF97_Basic_f3(
            dx_0vap, aux0_0.T_0member);
